-- Curated unnamed individuals (generated by source/gen_unnamed.py from source/cur_unnamed.py)
SET search_path TO bible;
BEGIN;

ALTER TABLE person ADD COLUMN IF NOT EXISTS name_status varchar(12) NOT NULL DEFAULT 'Named'
  CHECK (name_status IN ('Named','Descriptive'));

UPDATE person SET name_status = 'Descriptive' WHERE person_id IN ('canaanitish_woman_915', 'concubine_the_aramitess_954', 'daughter_of_herodias_983', 'daughter_of_lot_younger_984', 'daughter_of_lot_older_985', 'daughter_of_machir_986', 'daughter_of_meshullam_987', 'daughter_of_pharaoh_988', 'daughter_of_pharaoh_989', 'daughter_of_putiel_990', 'daughter_of_shuah_993', 'man_of_great_stature_1924', 'man_of_understanding_1925', 'mother_of_aholah_and_aholibah_2109', 'mother_of_lemuel_2110', 'mother_of_the_wife_of_simon_2111', 'mother_of_zebedees_children_2112', 'queen_of_sheba_2379', 'sister_of_tahpenes_2759', 'son_of_abinadab_2763', 'son_of_dekar_2764', 'son_of_geber_2765', 'son_of_hesed_2766', 'son_of_hur_2767', 'son_of_joiada_2768', 'sons_of_jashen_2769', 'the_giant_in_gath_2848', 'wife_of_ezekiel_2940', 'wife_of_simon_2943');
UPDATE person SET display_name = 'Daughter of Pharaoh, foster mother of Moses' WHERE person_id = 'daughter_of_pharaoh_988';
UPDATE person SET display_name = 'Daughter of Lot, older' WHERE person_id = 'daughter_of_lot_older_985';
UPDATE person SET display_name = 'Daughter of Lot, younger' WHERE person_id = 'daughter_of_lot_younger_984';
UPDATE person SET display_name = 'Canaanite mother of Shaul' WHERE person_id = 'canaanitish_woman_915';
UPDATE person SET display_name = 'Mother-in-law of Peter' WHERE person_id = 'mother_of_the_wife_of_simon_2111';
UPDATE person SET display_name = 'Wife of Peter' WHERE person_id = 'wife_of_simon_2943';
UPDATE person SET display_name = 'Mother of Zebedee''s sons' WHERE person_id = 'mother_of_zebedees_children_2112';

ON CONFLICT (person_id) DO NOTHING;

DELETE FROM relationship WHERE relationship_id > 100000;
ON CONFLICT DO NOTHING;

DROP VIEW IF EXISTS v_atlas_person, v_atlas_king, v_atlas_prophet, v_atlas_priest, v_atlas_judge, v_atlas_apostle;
CREATE VIEW v_atlas_person AS
SELECT p.* FROM person p WHERE p.primary_role = 'Person';
CREATE VIEW v_atlas_king AS
SELECT p.*, k.royal_title, k.kingdom, k.dynasty, k.reign_start_year, k.reign_end_year,
       k.reign_start_label, k.reign_end_label, k.reign_length_years, k.assessment
FROM person p JOIN king k USING (person_id) WHERE p.primary_role = 'King';
CREATE VIEW v_atlas_prophet AS
SELECT p.*, x.prophet_class, x.books_authored, x.ministry_start_year, x.ministry_end_year, x.audience, x.is_true_prophet
FROM person p JOIN prophet x USING (person_id) WHERE p.primary_role = 'Prophet';
CREATE VIEW v_atlas_priest AS
SELECT p.*, x.priestly_order, x.is_high_priest, x.served_at, x.tenure_start_year, x.tenure_end_year
FROM person p JOIN priest x USING (person_id) WHERE p.primary_role = 'Priest';
CREATE VIEW v_atlas_judge AS
SELECT p.*, x.judge_order, x.tribe_of_origin, x.years_judged, x.oppressor, x.start_year AS judgeship_start_year
FROM person p JOIN judge x USING (person_id) WHERE p.primary_role = 'Judge';
CREATE VIEW v_atlas_apostle AS
SELECT p.*, x.apostle_group, x.prior_occupation, x.calling_reference, x.death_tradition
FROM person p JOIN apostle x USING (person_id) WHERE p.primary_role = 'Apostle';
GRANT SELECT ON ALL TABLES IN SCHEMA bible TO timebase_reader;

COMMIT;
