INSERT INTO person (person_id, first_name, display_name, gender, testament, summary_of_life, summary_source, first_reference, verse_count, name_status) VALUES
('gerasene_demoniac_9001', 'Gerasene demoniac', 'Gerasene demoniac', 'Male', 'New Testament', 'Man possessed by a legion of demons who lived among the tombs in the country of the Gerasenes, breaking every chain put on him. Jesus cast the demons into a herd of pigs, which rushed into the sea. He begged to follow Jesus but was sent home to tell what had been done for him, and proclaimed it in the Decapolis. Matthew 8:28 describes two such men.', 'Curated', 'Mark 5:2', 34, 'Descriptive'),
('demoniac_of_capernaum_9002', 'Demoniac of the Capernaum synagogue', 'Demoniac of the Capernaum synagogue', 'Male', 'New Testament', 'Man with an unclean spirit who cried out in the synagogue at Capernaum that Jesus was the Holy One of God. Jesus rebuked the spirit and it came out of him, and Jesus'' fame spread through Galilee.', 'Curated', 'Mark 1:23', 11, 'Descriptive'),
('woman_with_issue_of_blood_9003', 'Woman with the issue of blood', 'Woman with the issue of blood', 'Female', 'New Testament', 'Woman who had suffered bleeding for twelve years and spent all she had on physicians. She touched the hem of Jesus'' garment in the crowd and was healed at once; Jesus told her, ''Daughter, your faith has made you well.''', 'Curated', 'Mark 5:25', 19, 'Descriptive'),
('daughter_of_jairus_9004', 'Daughter of Jairus', 'Daughter of Jairus', 'Female', 'New Testament', 'Twelve-year-old daughter of Jairus, a ruler of the synagogue. She died while her father was bringing Jesus to her; Jesus took her by the hand, said ''Talitha cumi'', and she rose and walked.', 'Curated', 'Mark 5:23', 40, 'Descriptive'),
('widow_of_nain_9005', 'Widow of Nain', 'Widow of Nain', 'Female', 'New Testament', 'Widow of the town of Nain whose only son was being carried out for burial. Jesus had compassion on her, told her not to weep, and raised her son to life.', 'Curated', 'Luke 7:12', 7, 'Descriptive'),
('son_of_widow_of_nain_9006', 'Son of the widow of Nain', 'Son of the widow of Nain', 'Male', 'New Testament', 'Only son of a widow of Nain. Jesus touched his bier and said ''Young man, I say to you, arise'', and he sat up and began to speak.', 'Curated', 'Luke 7:12', 7, 'Descriptive'),
('syrophoenician_woman_9007', 'Syrophoenician woman', 'Syrophoenician woman', 'Female', 'New Testament', 'Greek woman of Syrophoenician birth (a Canaanite in Matthew) from the region of Tyre and Sidon. She begged Jesus to drive a demon out of her daughter and answered that even the dogs eat the children''s crumbs; Jesus praised her faith and healed the girl.', 'Curated', 'Mark 7:25', 15, 'Descriptive'),
('daughter_of_syrophoenician_woman_9008', 'Daughter of the Syrophoenician woman', 'Daughter of the Syrophoenician woman', 'Female', 'New Testament', 'Young daughter of the Syrophoenician woman, possessed by an unclean spirit. Jesus healed her at a distance, and her mother found her lying in bed with the demon gone.', 'Curated', 'Mark 7:25', 7, 'Descriptive'),
('centurion_of_capernaum_9009', 'Centurion of Capernaum', 'Centurion of Capernaum', 'Male', 'New Testament', 'Roman centurion at Capernaum who had built the local synagogue. He asked Jesus to heal his servant, saying Jesus need only speak the word; Jesus marvelled that he had not found such faith in Israel.', 'Curated', 'Matthew 8:5', 19, 'Descriptive'),
('servant_of_the_centurion_9010', 'Servant of the centurion', 'Servant of the centurion', 'Male', 'New Testament', 'Highly valued servant of the centurion of Capernaum, paralysed and close to death. Jesus healed him from a distance.', 'Curated', 'Matthew 8:6', 19, 'Descriptive'),
('nobleman_of_capernaum_9011', 'Royal official of Capernaum', 'Royal official of Capernaum', 'Male', 'New Testament', 'Royal official whose son lay ill at Capernaum. He met Jesus at Cana, believed Jesus'' word that his son would live, and found that the fever had left the boy at that very hour; he and his household believed.', 'Curated', 'John 4:46', 9, 'Descriptive'),
('son_of_the_nobleman_9012', 'Son of the royal official', 'Son of the royal official', 'Male', 'New Testament', 'Son of a royal official of Capernaum, near death with fever, healed by Jesus'' word spoken at Cana. John counts it as Jesus'' second sign.', 'Curated', 'John 4:46', 9, 'Descriptive'),
('man_born_blind_9013', 'Man born blind', 'Man born blind', 'Male', 'New Testament', 'Beggar blind from birth whom Jesus healed on the Sabbath by putting clay on his eyes and sending him to wash in the pool of Siloam. Questioned by the Pharisees, he defended Jesus, was cast out of the synagogue, and then worshipped him.', 'Curated', 'John 9:1', 41, 'Descriptive'),
('paralytic_of_capernaum_9014', 'Paralytic lowered through the roof', 'Paralytic lowered through the roof', 'Male', 'New Testament', 'Paralysed man whose four friends lowered him through the roof of a crowded house in Capernaum. Jesus first forgave his sins, then told him to take up his bed and walk.', 'Curated', 'Mark 2:3', 30, 'Descriptive'),
('man_at_bethesda_9015', 'Man at the pool of Bethesda', 'Man at the pool of Bethesda', 'Male', 'New Testament', 'Man who had been ill for thirty-eight years and lay by the pool of Bethesda in Jerusalem. Jesus told him to rise, take up his bed and walk, and he was healed on the Sabbath.', 'Curated', 'John 5:5', 15, 'Descriptive'),
('man_with_withered_hand_9016', 'Man with the withered hand', 'Man with the withered hand', 'Male', 'New Testament', 'Man in a synagogue whose hand was withered. Jesus healed him on the Sabbath, and the Pharisees began to plot with the Herodians how to destroy Jesus.', 'Curated', 'Mark 3:1', 18, 'Descriptive'),
('samaritan_leper_9017', 'Samaritan leper', 'Samaritan leper', 'Male', 'New Testament', 'One of ten lepers Jesus cleansed on the border of Samaria and Galilee, and the only one who turned back to give thanks. He was a Samaritan.', 'Curated', 'Luke 17:15', 9, 'Descriptive'),
('leper_of_galilee_9018', 'Leper healed in Galilee', 'Leper healed in Galilee', 'Male', 'New Testament', 'Leper who knelt before Jesus saying ''If you will, you can make me clean.'' Jesus touched him and he was cleansed; told to say nothing, he spread the news everywhere.', 'Curated', 'Mark 1:40', 15, 'Descriptive'),
('bent_woman_9019', 'Bent woman', 'Bent woman', 'Female', 'New Testament', 'Woman bent double by a spirit of infirmity for eighteen years. Jesus laid hands on her in a synagogue on the Sabbath and she stood straight and glorified God.', 'Curated', 'Luke 13:11', 8, 'Descriptive'),
('man_with_dropsy_9020', 'Man with dropsy', 'Man with dropsy', 'Male', 'New Testament', 'Man swollen with dropsy whom Jesus healed on the Sabbath in the house of a ruler of the Pharisees.', 'Curated', 'Luke 14:2', 6, 'Descriptive'),
('boy_with_unclean_spirit_9021', 'Boy with an unclean spirit', 'Boy with an unclean spirit', 'Male', 'New Testament', 'Boy possessed since childhood by a spirit that threw him into fire and water. The disciples could not cast it out; Jesus did, after the boy''s father cried ''I believe; help my unbelief.''', 'Curated', 'Mark 9:17', 31, 'Descriptive'),
('father_of_possessed_boy_9022', 'Father of the possessed boy', 'Father of the possessed boy', 'Male', 'New Testament', 'Father who brought his possessed son to Jesus after the disciples failed to heal him, crying ''I believe; help my unbelief.''', 'Curated', 'Mark 9:17', 16, 'Descriptive'),
('deaf_mute_of_decapolis_9023', 'Deaf man of the Decapolis', 'Deaf man of the Decapolis', 'Male', 'New Testament', 'Deaf man with a speech impediment in the Decapolis. Jesus put his fingers in his ears, touched his tongue and said ''Ephphatha'', and he heard and spoke plainly.', 'Curated', 'Mark 7:32', 7, 'Descriptive'),
('blind_man_of_bethsaida_9024', 'Blind man of Bethsaida', 'Blind man of Bethsaida', 'Male', 'New Testament', 'Blind man of Bethsaida healed by Jesus in two stages: at first he saw men like trees walking, then he saw clearly.', 'Curated', 'Mark 8:22', 5, 'Descriptive'),
('mute_demoniac_9025', 'Mute demoniac', 'Mute demoniac', 'Male', 'New Testament', 'Man made mute by a demon. When Jesus cast it out he spoke, and the crowds marvelled while the Pharisees said Jesus cast out demons by the prince of demons.', 'Curated', 'Matthew 9:32', 3, 'Descriptive'),
('samaritan_woman_9026', 'Samaritan woman at the well', 'Samaritan woman at the well', 'Female', 'New Testament', 'Woman of Sychar in Samaria who met Jesus at Jacob''s well. He asked her for a drink, spoke of living water and told her of her five husbands; she ran to tell the town, and many Samaritans believed.', 'Curated', 'John 4:7', 36, 'Descriptive'),
('woman_caught_in_adultery_9027', 'Woman caught in adultery', 'Woman caught in adultery', 'Female', 'New Testament', 'Woman brought before Jesus in the Temple by scribes and Pharisees who wanted her stoned. Jesus said ''Let him who is without sin cast the first stone''; her accusers left, and he told her to go and sin no more. The passage is absent from the earliest manuscripts.', 'Curated', 'John 8:3', 9, 'Descriptive'),
('sinful_woman_9028', 'Sinful woman who anointed Jesus', 'Sinful woman who anointed Jesus', 'Female', 'New Testament', 'Woman known in the town as a sinner who wept on Jesus'' feet, wiped them with her hair and anointed them in the house of Simon the Pharisee. Jesus told her her sins were forgiven.', 'Curated', 'Luke 7:37', 15, 'Descriptive'),
('rich_young_ruler_9029', 'Rich young ruler', 'Rich young ruler', 'Male', 'New Testament', 'Wealthy young ruler who asked Jesus what he must do to inherit eternal life. Told to sell all he had and follow Jesus, he went away sorrowful, for he had great possessions.', 'Curated', 'Mark 10:17', 19, 'Descriptive'),
('poor_widow_9030', 'Poor widow at the treasury', 'Poor widow at the treasury', 'Female', 'New Testament', 'Poor widow who put two small coins into the Temple treasury. Jesus said she had given more than all the rich, because she gave all she had to live on.', 'Curated', 'Mark 12:42', 8, 'Descriptive'),
('scribe_not_far_9031', 'Scribe not far from the kingdom', 'Scribe not far from the kingdom', 'Male', 'New Testament', 'Scribe who asked Jesus which commandment is first of all and agreed with his answer; Jesus told him he was not far from the kingdom of God.', 'Curated', 'Mark 12:28', 7, 'Descriptive'),
('young_man_who_fled_9032', 'Young man who fled naked', 'Young man who fled naked', 'Male', 'New Testament', 'Young man wearing only a linen cloth who followed Jesus after his arrest in Gethsemane; when seized, he left the cloth and fled naked. Often identified by tradition with Mark.', 'Curated', 'Mark 14:51', 2, 'Descriptive'),
('servant_girl_of_high_priest_9033', 'Servant girl of the high priest', 'Servant girl of the high priest', 'Female', 'New Testament', 'Servant girl in the courtyard of the high priest who recognised Peter as one of Jesus'' companions, prompting his first denial.', 'Curated', 'Mark 14:66', 11, 'Descriptive'),
('wife_of_pilate_9034', 'Wife of Pilate', 'Wife of Pilate', 'Female', 'New Testament', 'Wife of Pontius Pilate who sent him a message during Jesus'' trial: ''Have nothing to do with that righteous man, for I have suffered much today in a dream because of him.'' Tradition names her Claudia Procula.', 'Curated', 'Matthew 27:19', 1, 'Descriptive'),
('penitent_thief_9035', 'Penitent thief', 'Penitent thief', 'Male', 'New Testament', 'One of two criminals crucified with Jesus. He rebuked the other for mocking Jesus and asked to be remembered; Jesus promised ''Today you will be with me in paradise.''', 'Curated', 'Luke 23:40', 7, 'Descriptive'),
('impenitent_thief_9036', 'Impenitent thief', 'Impenitent thief', 'Male', 'New Testament', 'One of two criminals crucified with Jesus, who railed at him: ''Are you not the Christ? Save yourself and us!''', 'Curated', 'Luke 23:39', 5, 'Descriptive'),
('centurion_at_the_cross_9037', 'Centurion at the cross', 'Centurion at the cross', 'Male', 'New Testament', 'Roman centurion in charge at the crucifixion who, seeing how Jesus died, said ''Truly this man was the Son of God.'' He later confirmed Jesus'' death to Pilate.', 'Curated', 'Matthew 27:54', 5, 'Descriptive'),
('lame_man_beautiful_gate_9038', 'Lame man at the Beautiful Gate', 'Lame man at the Beautiful Gate', 'Male', 'New Testament', 'Man lame from birth, more than forty years old, who begged at the Beautiful Gate of the Temple. Peter told him to walk in the name of Jesus Christ of Nazareth, and he leapt up praising God; the healing led to Peter and John''s arrest.', 'Curated', 'Acts 3:2', 13, 'Descriptive'),
('ethiopian_eunuch_9039', 'Ethiopian eunuch', 'Ethiopian eunuch', 'Male', 'New Testament', 'Ethiopian court official in charge of the treasury of Candace, queen of the Ethiopians. Reading Isaiah on the road from Jerusalem to Gaza, he heard Philip explain the passage, believed, and was baptised.', 'Curated', 'Acts 8:27', 14, 'Descriptive'),
('slave_girl_of_philippi_9040', 'Slave girl of Philippi', 'Slave girl of Philippi', 'Female', 'New Testament', 'Slave girl with a spirit of divination who earned her owners much money by fortune-telling. She followed Paul for days crying out; Paul cast the spirit out, and her owners had Paul and Silas beaten and jailed.', 'Curated', 'Acts 16:16', 4, 'Descriptive'),
('philippian_jailer_9041', 'Philippian jailer', 'Philippian jailer', 'Male', 'New Testament', 'Jailer at Philippi who put Paul and Silas in the inner prison. After an earthquake opened the doors he was about to kill himself, asked ''What must I do to be saved?'', and was baptised with his household that night.', 'Curated', 'Acts 16:23', 14, 'Descriptive'),
('lame_man_of_lystra_9042', 'Lame man of Lystra', 'Lame man of Lystra', 'Male', 'New Testament', 'Man of Lystra crippled from birth who had never walked. Paul, seeing he had faith to be healed, told him to stand up, and he sprang up and walked; the crowd took Paul and Barnabas for gods.', 'Curated', 'Acts 14:8', 3, 'Descriptive'),
('sister_of_paul_9043', 'Sister of Paul', 'Sister of Paul', 'Female', 'New Testament', 'Paul''s sister, mentioned only as the mother of the young man who warned Paul of a plot against his life in Jerusalem.', 'Curated', 'Acts 23:16', 1, 'Descriptive'),
('nephew_of_paul_9044', 'Nephew of Paul', 'Nephew of Paul', 'Male', 'New Testament', 'Son of Paul''s sister who heard of a plot by more than forty men to ambush Paul, and told Paul and the Roman tribune, who moved Paul to Caesarea under guard.', 'Curated', 'Acts 23:16', 7, 'Descriptive'),
('wife_of_noah_9045', 'Wife of Noah', 'Wife of Noah', 'Female', 'Old Testament', 'Wife of Noah who entered the ark with him, their three sons and their sons'' wives, and was preserved through the Flood.', 'Curated', 'Genesis 6:18', 5, 'Descriptive'),
('wife_of_shem_9046', 'Wife of Shem', 'Wife of Shem', 'Female', 'Old Testament', 'Wife of Shem, one of the eight people saved in Noah''s ark.', 'Curated', 'Genesis 7:13', 5, 'Descriptive'),
('wife_of_ham_9047', 'Wife of Ham', 'Wife of Ham', 'Female', 'Old Testament', 'Wife of Ham, one of the eight people saved in Noah''s ark.', 'Curated', 'Genesis 7:13', 5, 'Descriptive'),
('wife_of_japheth_9048', 'Wife of Japheth', 'Wife of Japheth', 'Female', 'Old Testament', 'Wife of Japheth, one of the eight people saved in Noah''s ark.', 'Curated', 'Genesis 7:13', 5, 'Descriptive'),
('wife_of_lot_9049', 'Wife of Lot', 'Wife of Lot', 'Female', 'Old Testament', 'Wife of Lot who fled Sodom with him and their two daughters. She looked back as the city was destroyed and became a pillar of salt; Jesus cites her as a warning: ''Remember Lot''s wife.''', 'Curated', 'Genesis 19:15', 4, 'Descriptive'),
('wife_of_potiphar_9050', 'Wife of Potiphar', 'Wife of Potiphar', 'Female', 'Old Testament', 'Wife of Potiphar, captain of Pharaoh''s guard. She repeatedly tried to seduce Joseph; when he fled leaving his garment, she accused him of assault and he was thrown into prison.', 'Curated', 'Genesis 39:7', 14, 'Descriptive'),
('chief_cupbearer_9051', 'Pharaoh''s chief cupbearer', 'Pharaoh''s chief cupbearer', 'Male', 'Old Testament', 'Pharaoh''s chief cupbearer (butler), imprisoned with Joseph. Joseph interpreted his dream of restoration; he was restored but forgot Joseph for two years, until he recalled him when Pharaoh''s dreams went uninterpreted.', 'Curated', 'Genesis 40:1', 28, 'Descriptive'),
('chief_baker_9052', 'Pharaoh''s chief baker', 'Pharaoh''s chief baker', 'Male', 'Old Testament', 'Pharaoh''s chief baker, imprisoned with Joseph. Joseph interpreted his dream of three baskets to mean death within three days, and Pharaoh hanged him on his birthday.', 'Curated', 'Genesis 40:1', 22, 'Descriptive'),
('wife_of_manoah_9053', 'Wife of Manoah', 'Wife of Manoah', 'Female', 'Old Testament', 'Barren wife of Manoah of the tribe of Dan. The angel of the Lord told her she would bear a son who must be a Nazirite from the womb; she became the mother of Samson.', 'Curated', 'Judges 13:2', 23, 'Descriptive'),
('woman_of_thebez_9054', 'Woman of Thebez', 'Woman of Thebez', 'Female', 'Old Testament', 'Woman who dropped an upper millstone from the tower of Thebez onto Abimelech''s head, crushing his skull, as he besieged the city.', 'Curated', 'Judges 9:53', 2, 'Descriptive'),
('armor_bearer_of_abimelech_9055', 'Armor-bearer of Abimelech', 'Armor-bearer of Abimelech', 'Male', 'Old Testament', 'Young armor-bearer who ran Abimelech through with his sword at his master''s command, so that it would not be said a woman killed him.', 'Curated', 'Judges 9:54', 1, 'Descriptive'),
('daughter_of_jephthah_9056', 'Daughter of Jephthah', 'Daughter of Jephthah', 'Female', 'Old Testament', 'Only child of Jephthah, who came out dancing to meet him after his victory over the Ammonites and so fell under his vow. She asked for two months to mourn on the mountains, and the daughters of Israel lamented her yearly.', 'Curated', 'Judges 11:34', 7, 'Descriptive'),
('wife_of_samson_9057', 'Timnite wife of Samson', 'Timnite wife of Samson', 'Female', 'Old Testament', 'Philistine woman of Timnah whom Samson married. Pressed by her countrymen, she coaxed the answer to his riddle from him and told them; she was later given to his companion and burned with her father by the Philistines.', 'Curated', 'Judges 14:1', 26, 'Descriptive'),
('mother_of_sisera_9058', 'Mother of Sisera', 'Mother of Sisera', 'Female', 'Old Testament', 'Mother of the Canaanite commander Sisera, pictured in the Song of Deborah watching through the lattice and wondering why his chariot was so long in coming.', 'Curated', 'Judges 5:28', 3, 'Descriptive'),
('levite_of_ephraim_9059', 'Levite of Ephraim', 'Levite of Ephraim', 'Male', 'Old Testament', 'Levite from the hill country of Ephraim whose concubine was abused to death by men of Gibeah. He cut her body into twelve pieces and sent them through Israel, provoking war against Benjamin.', 'Curated', 'Judges 19:1', 34, 'Descriptive'),
('concubine_of_the_levite_9060', 'Concubine of the Levite', 'Concubine of the Levite', 'Female', 'Old Testament', 'Concubine from Bethlehem in Judah of a Levite of Ephraim. Handed over to a mob at Gibeah, she was abused through the night and died at the door; the outrage led to civil war with Benjamin.', 'Curated', 'Judges 19:1', 33, 'Descriptive'),
('man_of_god_rebuked_eli_9061', 'Man of God who rebuked Eli', 'Man of God who rebuked Eli', 'Male', 'Old Testament', 'Prophet who came to Eli at Shiloh and announced judgement on his house for honouring his sons above God, foretelling that Hophni and Phinehas would die on one day.', 'Curated', '1 Samuel 2:27', 10, 'Descriptive'),
('armor_bearer_of_jonathan_9062', 'Armor-bearer of Jonathan', 'Armor-bearer of Jonathan', 'Male', 'Old Testament', 'Young man who climbed with Jonathan to attack the Philistine garrison at Michmash, saying ''I am with you heart and soul''; the two of them began the rout of the Philistines.', 'Curated', '1 Samuel 14:1', 17, 'Descriptive'),
('medium_of_endor_9063', 'Medium of Endor', 'Medium of Endor', 'Female', 'Old Testament', 'Woman at Endor who consulted the dead. Saul, in disguise, asked her to bring up Samuel on the eve of battle; she saw Samuel rise, recognised Saul, and afterwards fed him.', 'Curated', '1 Samuel 28:7', 19, 'Descriptive'),
('armor_bearer_of_saul_9064', 'Armor-bearer of Saul', 'Armor-bearer of Saul', 'Male', 'Old Testament', 'Saul''s armor-bearer at Mount Gilboa who refused to kill his wounded master; when Saul fell on his own sword, he did the same and died with him.', 'Curated', '1 Samuel 31:4', 5, 'Descriptive'),
('amalekite_messenger_9065', 'Amalekite who reported Saul''s death', 'Amalekite who reported Saul''s death', 'Male', 'Old Testament', 'Young Amalekite who brought David Saul''s crown and armlet and claimed to have killed Saul at his request. David had him executed for striking the Lord''s anointed.', 'Curated', '2 Samuel 1:2', 16, 'Descriptive'),
('wise_woman_of_tekoa_9066', 'Wise woman of Tekoa', 'Wise woman of Tekoa', 'Female', 'Old Testament', 'Woman Joab brought from Tekoa to tell David a made-up story of a son in danger, to persuade him to allow the banished Absalom to return. David saw Joab''s hand in it but agreed.', 'Curated', '2 Samuel 14:2', 19, 'Descriptive'),
('wise_woman_of_abel_9067', 'Wise woman of Abel', 'Wise woman of Abel', 'Female', 'Old Testament', 'Woman of Abel of Beth-maacah who negotiated with Joab from the wall during his siege, persuaded the city to throw down the rebel Sheba''s head, and so saved the city.', 'Curated', '2 Samuel 20:16', 7, 'Descriptive'),
('true_mother_before_solomon_9068', 'True mother before Solomon', 'True mother before Solomon', 'Female', 'Old Testament', 'One of two women who brought a dispute over a living child to Solomon. When the king ordered the child cut in two, she gave up her claim to save its life, and Solomon gave the child to her.', 'Curated', '1 Kings 3:16', 13, 'Descriptive'),
('false_mother_before_solomon_9069', 'False mother before Solomon', 'False mother before Solomon', 'Female', 'Old Testament', 'Woman who claimed another''s child as her own after her son died in the night, and agreed that the child should be divided, revealing to Solomon that she was not the mother.', 'Curated', '1 Kings 3:16', 13, 'Descriptive'),
('man_of_god_from_judah_9070', 'Man of God from Judah', 'Man of God from Judah', 'Male', 'Old Testament', 'Prophet who cried against Jeroboam''s altar at Bethel and foretold Josiah. Jeroboam''s hand withered and was restored at his prayer; deceived by an old prophet into eating in Bethel against God''s command, he was killed by a lion.', 'Curated', '1 Kings 13:1', 34, 'Descriptive'),
('old_prophet_of_bethel_9071', 'Old prophet of Bethel', 'Old prophet of Bethel', 'Male', 'Old Testament', 'Old prophet of Bethel who lied that an angel had told him to bring the man of God from Judah home to eat. After the man of God was killed, he buried him in his own tomb and asked to be buried beside him.', 'Curated', '1 Kings 13:11', 23, 'Descriptive'),
('wife_of_jeroboam_9072', 'Wife of Jeroboam', 'Wife of Jeroboam', 'Female', 'Old Testament', 'Wife of Jeroboam I, sent in disguise to the blind prophet Ahijah at Shiloh to ask about their sick son Abijah. Ahijah recognised her and foretold the boy''s death and the end of Jeroboam''s house.', 'Curated', '1 Kings 14:2', 17, 'Descriptive'),
('widow_of_zarephath_9073', 'Widow of Zarephath', 'Widow of Zarephath', 'Female', 'Old Testament', 'Widow of Zarephath in Sidon who shared her last flour and oil with Elijah during the drought; her jar of flour and jug of oil did not run out. Elijah later raised her son.', 'Curated', '1 Kings 17:9', 19, 'Descriptive'),
('son_of_widow_of_zarephath_9074', 'Son of the widow of Zarephath', 'Son of the widow of Zarephath', 'Male', 'Old Testament', 'Son of the widow of Zarephath who fell ill and stopped breathing. Elijah stretched himself on the boy three times and prayed, and he revived.', 'Curated', '1 Kings 17:12', 9, 'Descriptive'),
('widow_with_the_oil_9075', 'Widow with the jar of oil', 'Widow with the jar of oil', 'Female', 'Old Testament', 'Widow of one of the sons of the prophets whose creditor was about to take her two sons as slaves. Elisha told her to pour her little oil into borrowed vessels; it filled them all, and she sold it to pay the debt.', 'Curated', '2 Kings 4:1', 7, 'Descriptive'),
('shunammite_woman_9076', 'Shunammite woman', 'Shunammite woman', 'Female', 'Old Testament', 'Wealthy woman of Shunem who built a room for Elisha. He promised her a son; when the boy died she went to Elisha, who raised him. Later her land was restored to her by the king.', 'Curated', '2 Kings 4:8', 36, 'Descriptive'),
('husband_of_shunammite_9077', 'Husband of the Shunammite woman', 'Husband of the Shunammite woman', 'Male', 'Old Testament', 'Elderly husband of the Shunammite woman, father of the son Elisha promised and later raised.', 'Curated', '2 Kings 4:9', 9, 'Descriptive'),
('son_of_shunammite_9078', 'Son of the Shunammite woman', 'Son of the Shunammite woman', 'Male', 'Old Testament', 'Son born to the Shunammite woman as Elisha foretold. He died in his mother''s lap after complaining of his head; Elisha stretched himself on him and he sneezed seven times and opened his eyes.', 'Curated', '2 Kings 4:17', 26, 'Descriptive'),
('servant_girl_of_naaman_9079', 'Naaman''s servant girl', 'Naaman''s servant girl', 'Female', 'Old Testament', 'Young Israelite girl taken captive by Aramean raiders who served Naaman''s wife. She told her mistress that the prophet in Samaria could cure Naaman of his leprosy.', 'Curated', '2 Kings 5:2', 3, 'Descriptive'),
('wife_of_job_9080', 'Wife of Job', 'Wife of Job', 'Female', 'Old Testament', 'Wife of Job who, after his children and health were taken, told him ''Curse God and die.'' Job answered that they should accept evil from God as well as good.', 'Curated', 'Job 2:9', 4, 'Descriptive'),
('nearer_kinsman_of_ruth_9081', 'Nearer kinsman of Ruth', 'Nearer kinsman of Ruth', 'Male', 'Old Testament', 'Relative of Elimelech with the first right to redeem Naomi''s land. He declined when it meant marrying Ruth, and gave Boaz his sandal at the city gate, leaving Boaz free to redeem.', 'Curated', 'Ruth 3:12', 10, 'Descriptive'),
('queen_mother_of_belshazzar_9082', 'Queen mother of Belshazzar', 'Queen mother of Belshazzar', 'Female', 'Old Testament', 'Queen (usually understood as the queen mother) who came into Belshazzar''s feast after the writing appeared on the wall, and told the king to summon Daniel to interpret it.', 'Curated', 'Daniel 5:10', 3, 'Descriptive')
INSERT INTO relationship (relationship_id, from_person_id, relationship_type, to_person_id, scripture_reference, source) VALUES
(100001, 'jesus_905', 'Healed', 'gerasene_demoniac_9001', 'Mark 5:8', 'Curated'),
